      SUBROUTINE DFRINRCC     CALCULATES PARTIAL DERIVATIVES OF RBEND FRINGE FIELD MATRIXC     ELEMENTS WITH RESPECT TO QUANTITIES DESCRIBING THE MAIN BODYC     OF THE MAGNETCC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'ELM0E.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM17A.CIN'      INCLUDE 'ELM28.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'R.CIN'CC     LOCAL VARIABLESC      INTEGER  IANG, IB, IL, IRHO      REAL  BEV, CSA2, HV, SNA2CC----------------------------------------------------------------      LINEAR = .FALSE.      IL = IPTOJ(NL)      IB = IPTOJ(NBV)      IRHO = IPTOJ(NRHO)      IANG = IPTOJ(NANG)      GO TO (10,20,30,40), JVC   10 IF (IB .NE. 0) THEN        SNA2 = 0.5*H0*LRBEND        CSA2 = SQRT(1.0 - SNA2**2)        BEV = 0.5*H0*UNITI(8)/CSA2        GO TO 110      ELSE IF (IRHO .NE. 0) THEN        SNA2 = 0.5*H0*LRBEND        CSA2 = SQRT(1.0 - SNA2**2)        BEV = 0.5*H0*UNITI(8)/CSA2        GO TO 110      ELSE IF (IANG .NE. 0) THEN        HV = - H0*UNITI(8)*DPARM/LRBEND        GO TO 100      ENDIF      GO TO 200C   20 IF (IL .NE. 0) THEN        HV = UNITI(9)*DPARM/PREF        SNA2 = 0.5*H0*LRBEND        CSA2 = SQRT(1.0 - SNA2**2)        BEV = 0.5*LRBEND*UNITI(9)/(PREF*CSA2)        GO TO 120      ELSE IF (IANG .NE. 0) THEN        HV = UNITI(9)*DPARM/PREF        GO TO 100      ENDIF      GO TO 200C   30 IF (IL .NE. 0) THEN        HV = - H0**2*DPARM*UNITI(8)        SNA2 = 0.5*H0*LRBEND        CSA2 = SQRT(1.0 - SNA2**2)        BEV = - 0.5*H0**2*LRBEND*UNITI(8)/CSA2        GO TO 120      ELSE IF (IANG .NE. 0) THEN        HV = - H0**2*DPARM*UNITI(8)        GO TO 100      ENDIF      GO TO 200C   40 BEV = 0.5*UNITI(7)      IF (IL .NE. 0) THEN        SNA2 = 0.5*H0*LRBEND        CSA2 = SQRT(1.0 - SNA2**2)        HV = CSA2*DPARM*UNITI(7)/LRBEND        GO TO 120      ELSE IF (IB .NE. 0 .OR. IRHO .NE. 0) THEN        GO TO 110      ENDIF      GO TO 200C  100 RV(2,1) = HV*TB      RV(4,3) = - HV*TB + 4.0*HV*H0*APB(2)*LAYL*SB*(SB**2 + TB**2)      GO TO 200C  110 RV(2,1) = H0*SB**2*BEV      RV(4,3) = - H0*SB**2*BEV      GO TO 200C  120 RV(2,1) = HV*TB + H0*SB**2*BEV      RV(4,3) = - HV*TB + 4.0*HV*H0*APB(2)*LAYL*SB*(SB**2 + TB**2)     1          - H0*SB**2*BEV     2          + 4.0*H0**2*APB(2)*LAYL*TB*SB*(5.0*SB**2 + TB**2)     3            *BEV      GO TO 200C  200 RETURN      END